{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE MapleMonk.Zouk_D2C_App_Target_vs_Achieved AS WITH Target AS ( SELECT Safe.parse_date(\'%Y-%m-%d\',Start_Date) AS Target_Date, Channel, safe_cast(REPLACE(Target,\",\",\'\' )AS float64) AS Target FROM `MapleMonk.Zouk_d2c_App_Target` ) , Sales AS ( SELECT Date, MARKETPLACE, CASE WHEN Lower(MARKETPLACE) like any (\'shopify android app\', \'shopify app\') THEN \'Android\' WHEN Lower(MARKETPLACE) like \'shopify ios app\' THEN \'iOS\' ELSE \'App\' END AS Channel, new_customer_flag, customer_id_final, REFERENCE_CODE, Payment_Mode, sum(Quantity) AS Quantity, sum(Net_Revenue) AS Net_Revenue FROM `MapleMonk.Zouk_DTC_Net_Sales` WHERE Lower(MARKETPLACE) like \'%app%\' and Date < Current_Date(\'Asia/Kolkata\') GROUP BY 1,2,3,4,5,6,7 ), Combined AS ( SELECT COALESCE(t.Target_Date,s.Date) AS Date, Marketplace, COALESCE(s.Channel,t.Channel) AS Channel, new_customer_flag, customer_id_final, Reference_code, Payment_Mode, Quantity, Net_Revenue, Ifnull(t.Target,0) AS Target, ifnull(a4.Session,0) AS Session, ifnull(a6.total_install,0) AS Total_Install, ifnull(a3.meta_installs,0) AS Meta_Install, ifnull(a5.uninstalls,0) AS Uninstall, ifnull(a1.Ad_Spent,0) AS Amount_Spent, ifnull(a2.CPI,0) AS Meta_Ad_CPI, ROW_NUMBER() OVER (PARTITION BY coalesce(t.target_date,s.Date), coalesce(t.channel,s.Channel) ORDER BY s.Reference_Code) AS rn FROM Target t FULL OUTER JOIN Sales s ON t.Target_Date = s.Date AND lower(t.Channel) = lower(s.Channel) FULL OUTER JOIN ( SELECT SAFE.PARSE_DATE(\'%Y-%m-%d\',Date) AS Date, Channel, SAFE_CAST(REPLACE(Value,\',\',\'\')AS FLOAT64) AS Ad_Spent FROM `MapleMonk.Zouk_d2c_App_Ad_Spent` ) a1 ON COALESCE(t.Target_Date,s.Date) = a1.Date AND LOWER(COALESCE(s.Channel,t.Channel)) = LOWER(a1.Channel) FULL OUTER JOIN ( SELECT SAFE.PARSE_DATE(\'%Y-%m-%d\',Date) AS Date, Channel, SAFE_CAST(REPLACE(Value,\',\',\'\')AS FLOAT64) AS CPI FROM `MapleMonk.Zouk_d2c_App_CPI` ) a2 ON COALESCE(t.Target_Date,s.Date) = a2.Date AND LOWER(COALESCE(s.Channel,t.Channel)) = LOWER(a2.Channel) FULL OUTER JOIN ( SELECT SAFE.PARSE_DATE(\'%Y-%m-%d\',Date) AS Date, Channel, SAFE_CAST(REPLACE(Value,\',\',\'\')AS FLOAT64) AS meta_installs FROM `MapleMonk.Zouk_d2c_App_Installs_Meta` ) a3 ON COALESCE(t.Target_Date,s.Date) = a3.Date AND LOWER(COALESCE(s.Channel,t.Channel)) = LOWER(a3.Channel) FULL OUTER JOIN ( SELECT SAFE.PARSE_DATE(\'%Y-%m-%d\',Date) AS Date, Channel, SAFE_CAST(REPLACE(Value,\',\',\'\') AS FLOAT64) AS Session FROM `MapleMonk.Zouk_d2c_App_Session` ) a4 ON COALESCE(t.Target_Date,s.Date) = a4.Date AND LOWER(COALESCE(s.Channel,t.Channel)) = LOWER(a4.Channel) FULL OUTER JOIN ( SELECT SAFE.PARSE_DATE(\'%Y-%m-%d\',Date) AS Date, Channel, SAFE_CAST(REPLACE(Value,\',\',\'\')AS FLOAT64) AS Uninstalls FROM `MapleMonk.Zouk_d2c_App_Uninstall` ) a5 ON COALESCE(t.Target_Date,s.Date) = a5.Date AND LOWER(COALESCE(s.Channel,t.Channel)) = LOWER(a5.Channel) FULL OUTER JOIN ( SELECT SAFE.PARSE_DATE(\'%Y-%m-%d\',Date) AS Date, Channel, SAFE_CAST(REPLACE(Value,\',\',\'\')AS FLOAT64) AS total_install FROM `MapleMonk.Zouk_d2c_App_Install_Total` ) a6 ON COALESCE(t.Target_Date,s.Date) = a6.Date AND LOWER(COALESCE(s.Channel,t.Channel)) = LOWER(a6.Channel) ) SELECT Date, MARKETPLACE, Channel, new_customer_flag, customer_id_final, Reference_code, Payment_Mode, Quantity, Net_Revenue, IF(rn = 1, IFNULL(Target,0), 0) AS Target, IF(rn = 1, IFNULL(Session, 0), 0) AS Session, IF(rn = 1, IFNULL(Total_Install, 0), 0) AS Total_Install, IF(rn = 1, IFNULL(Meta_Install, 0), 0) AS Meta_Install, IF(rn = 1, IFNULL(Uninstall, 0), 0) AS Uninstall, IF(rn = 1, IFNULL(Amount_Spent, 0), 0) AS Amount_Spent, IF(rn = 1, IFNULL(Meta_Ad_CPI, 0), 0) AS Meta_Ad_CPI FROM Combined ORDER BY Date, Channel, rn ; CREATE OR REPLACE TABLE MapleMonk.zouk_app_summary_d2c AS select CAST(Metrics AS STRING) AS Metrics, CAST(REPLACE(Android,\',\',\'\') AS INT64) AS Android, CAST(REPLACE(iOS,\',\',\'\') AS INT64) AS iOS, CAST(REPLACE(Total,\',\',\'\') AS INT64) AS Total from `MapleMonk.Zouk_d2c_App_Summary` ;",
                    "transaction": true
                }
            ) }}
